    activity: { en: "Choose one problem. Define the user, the problem and the one thing your app must do brilliantly. Sketch three screens.", ar: "اختر مشكلة واحدة. حدّد المستخدم والمشكلة والشيء الواحد الذي يجب أن ينجزه التطبيق بإتقان. ارسم ثلاث شاشات." },
    challenge: { en: "Another team becomes the user and tests your paper prototype. They may request one change. Decide whether to accept it and explain why.", ar: "تتحول مجموعة أخرى إلى مستخدم وتجرب النموذج الورقي. يحق لها طلب تغيير واحد. قرروا قبوله أو رفضه واشرحوا السبب." },
    flourish: { en: "Responsible technology solves a problem without creating a worse one. What privacy, safety or fairness risk could your app create?", ar: "التقنية المسؤولة تحل مشكلة دون صنع مشكلة أكبر. ما مخاطر الخصوصية أو السلامة أو العدالة التي قد يسببها تطبيقكم؟" },
