    equipment: { en: "board, paper and pens", ar: "السبورة والورق والأقلام" },
    starter: { en: "Draw two columns: Helps Learning / Gets in the Way. Add behaviours, routines or conditions, not names of people.", ar: "ارسم عمودين: يساعد التعلم / يعيق التعلم. أضف سلوكيات أو روتيناً أو ظروفاً، لا أسماء أشخاص." },
    activity: { en: "Groups combine lists and choose their top five in each column. For every problem, add a realistic replacement behaviour.", ar: "تجمع المجموعات قوائمها وتختار أهم خمسة في كل عمود. ولكل مشكلة، أضف سلوكاً بديلاً واقعياً." },
    challenge: { en: "Identify behaviours that can be helpful in one context and unhelpful in another, such as talking, moving, using a device or helping a friend.", ar: "حدد سلوكيات قد تكون مفيدة في سياق وضارة في سياق آخر، مثل الكلام أو الحركة أو استخدام جهاز أو مساعدة صديق." },
    flourish: { en: "Which Flourish values help us decide when a behaviour is appropriate rather than relying on a giant list of rules?", ar: "أي قيم من الازدهار تساعدنا على تحديد متى يكون السلوك مناسباً بدلاً من الاعتماد على قائمة ضخمة من القواعد؟" },
    exit: { en: "Choose one behaviour you personally control that would make this class easier to learn in.", ar: "اختر سلوكاً واحداً تتحكم فيه شخصياً وسيجعل التعلم في هذا الصف أسهل." },
    extension: { en: "Write a one-sentence principle that could replace several individual rules on your list.", ar: "اكتب مبدأً من جملة واحدة يمكن أن يحل محل عدة قواعد منفصلة في قائمتك." },
    teacherLens: { en: "Notice whether students frame success as something teachers enforce or something everyone contributes to.", ar: "لاحظ هل يرى الطلاب النجاح شيئاً يفرضه المعلم أم شيئاً يساهم فيه الجميع." }
