    focuses: ["communication", "expectations", "confidence"],
    ages: ["y3-4", "y5-6", "y7-9", "y10-12"],
    title: { en: "Repair the Moment", ar: "أصلح الموقف" },
    summary: { en: "Practise what a useful conversation sounds like after a mistake, disagreement or poor choice.", ar: "تدرّب على شكل الحوار المفيد بعد خطأ أو خلاف أو اختيار غير مناسب." },
    learning: { en: "reflection, empathy, communication and restoration", ar: "التأمل والتعاطف والتواصل والإصلاح" },
