    starter: { en: "Think of praise you have received that actually meant something. What made it feel genuine rather than automatic?", ar: "فكر في مديح تلقيته وكان له معنى حقيقي. ما الذي جعله صادقاً لا آلياً؟" },
    activity: { en: "Teams design ways to notice Ready, Respectful, Responsible and Safe. Include everyday recognition, home contact and bigger milestones.", ar: "تصمم الفرق طرقاً لملاحظة قيم مستعد ومحترم ومسؤول وآمن. أضيفوا تقديراً يومياً وتواصلاً مع المنزل ومحطات إنجاز أكبر." },
    challenge: { en: "Stress-test your ideas: Could the system become unfair, embarrassing, easy to game or focused only on already-successful students? Improve it.", ar: "اختبروا أفكاركم: هل يمكن أن يصبح النظام غير عادل أو محرجاً أو سهل التلاعب أو مركزاً فقط على الطلاب الناجحين أصلاً؟ حسّنوه." },
    flourish: { en: "Good recognition names the behaviour, not just ‘good job’. Write one specific example for each Flourish value.", ar: "التقدير الجيد يسمّي السلوك، لا يكتفي بعبارة «أحسنت». اكتب مثالاً محدداً لكل قيمة من قيم الازدهار." },
    exit: { en: "Vote privately: Which kind of recognition would motivate you most, and which would you least want?", ar: "صوّت بسرية: أي نوع من التقدير سيحفزك أكثر؟ وأي نوع لا ترغب فيه؟" },
    extension: { en: "Create a simple recognition ladder that celebrates consistency and growth, not just one-off high achievement.", ar: "أنشئ مسار تقدير بسيطاً يحتفي بالاتساق والنمو، لا بالإنجاز العالي لمرة واحدة فقط." },
    teacherLens: { en: "Excellent consultation data for the positive side of Flourish. Note differences by age and what students find authentic.", ar: "هذه بيانات ممتازة للاستشارة حول الجانب الإيجابي من الازدهار. لاحظ الاختلافات حسب العمر وما يراه الطلاب صادقاً وذا معنى." }
