    starter: { en: "Is treating everyone fairly always the same as treating everyone exactly the same? Give a non-school example.", ar: "هل تعني معاملة الجميع بعدل دائماً معاملتهم بالطريقة نفسها تماماً؟ أعط مثالاً من خارج المدرسة." },
    activity: { en: "Compare pairs of fictional situations that look similar but have different context. Decide what an adult needs to know before responding.", ar: "قارن أزواجاً من المواقف الخيالية التي تبدو متشابهة لكن سياقها مختلف. قرر ما الذي يحتاج البالغ إلى معرفته قبل الاستجابة." },
    challenge: { en: "For each pair, identify what should stay consistent: expectation, language, process, consequence, support or recording.", ar: "لكل زوج، حدد ما الذي يجب أن يبقى متسقاً: التوقع، اللغة، الإجراء، العاقبة، الدعم أم التسجيل." },
    flourish: { en: "Which Flourish value is most useful when making a fair decision with incomplete information?", ar: "أي قيمة من قيم الازدهار أكثر فائدة عند اتخاذ قرار عادل بمعلومات غير مكتملة؟" },
